<?php
if(PHP_SAPI!=='cli'||!defined('IN_PHPBB')){return;}
require_once __DIR__.'/arcade-comment-native-fixture.php';
function cmtp_prepare($locale='english')
{
 cmt_prepare($locale);tn_sql("INSERT INTO fixture_ina_comment(comment_id,comment_game_name,comment_user_id,comment_username,comment_text,comment_edit_time,comment_edit_count,comment_edit_user_id) VALUES(44,'synthetic-rating',9,'Old name','Middle &amp; Grüße 😀',123,1,10),(45,'synthetic-rating',10,'Second','Last',NULL,0,NULL),(46,'synthetic-rating',-1,'Former fixture','Former text',NULL,0,NULL),(47,'synthetic-rating',99,'Orphan name','Orphan text',NULL,0,NULL)");
 tn_sql("INSERT INTO fixture_ina_scores(game_name,player_id,score,date,time_taken) VALUES('synthetic-rating',9,10,1,99),('synthetic-rating',9,20,2,3),('synthetic-rating',9,20,2,4),('synthetic-rating',9,30,3,8),('synthetic-rating',9,30,4,2),('synthetic-rating',10,25,5,6),('second-game',9,999,1,1)");
}
function cmtp_call($options=array(),$comment=0)
{
 try{return array('ok'=>true,'value'=>phpbb_arcade_comment_view($GLOBALS['db'],$GLOBALS['userdata'],1,$comment,$options),'error'=>'');}catch(PhpbbArcadeRatingFailure$e){return array('ok'=>false,'value'=>null,'error'=>$e->getMessage());}
}
function cmtp_ids($page){$ids=array();foreach($page['rows']as$row){$ids[]=(int)$row['comment_id'];}return$ids;}
function tp_arcade_comment_pages()
{
 global $db,$host,$password,$schema,$userdata,$tn_app,$tp_hook;
 $db->sql_close();$db=new CmtSource($host,'root',$password,$schema,false);
 foreach(array('arcade_comment_require_token','arcade_comment_can_manage')as$name){if(!function_exists($name)){$source=file_get_contents($tn_app.'arcade_comment.php');nt_check(preg_match('/^function '.$name.'\(.*?^\}/ms',$source,$m)===1,'Actual controller policy helpers');eval($m[0]);}}
 $cases=$views=$faults=0;
 foreach(array('english','german')as$locale){foreach(array('ASC','DESC')as$sort){foreach(array(1,2,3,10)as$size){
  cmtp_prepare($locale);$before=tp_snapshot();$expected=array(42,44,45,46,47);if($sort==='DESC'){$expected=array_reverse($expected);}$all=array();
  for($offset=0;$offset<5;$offset+=$size){$r=cmtp_call(array('sort'=>$sort,'size'=>$size,'start'=>$offset));nt_check($r['ok'],'Current coherent comment page');$value=$r['value'];nt_check($value['game']['comments_count']===5&&$value['page']['start']===$offset&&$value['page']['size']===$size&&$value['page']['sort']===$sort,'Count/page boundary agree');$ids=cmtp_ids($value['page']);nt_check($ids===array_slice($expected,$offset,$size),'One row per actual comment in order');$all=array_merge($all,$ids);$cases++;}
  nt_check($all===$expected&&tp_snapshot()===$before&&tp_released(),'Entire pagination has no duplicate/missing comments or data changes');$cases++;
  foreach($expected as$index=>$id){$r=cmtp_call(array('sort'=>$sort,'size'=>$size,'start'=>999999),$id);$start=(int)(floor($index/$size)*$size);nt_check($r['ok']&&$r['value']['page']['start']===$start&&in_array($id,cmtp_ids($r['value']['page']),true),'Selected anchor follows actual sort and overrides stale offset');$cases++;}
  $GLOBALS['board_config']['posts_per_page']=$size;
  foreach(array('list','selected','last','unrounded','empty-sort')as$kind){$get=array('game_id'=>'1','sort_order'=>$sort);$expected_ids=array_slice($expected,0,$size);if($kind==='selected'){$get=array('comment_id'=>'42','sort_order'=>$sort);$index=array_search(42,$expected,true);$expected_ids=array_slice($expected,(int)(floor($index/$size)*$size),$size);}elseif($kind==='last'){$get['start']='999999';$expected_ids=array_slice($expected,(int)(floor(4/$size)*$size),$size);}elseif($kind==='unrounded'){$get['start']='1';$expected_ids=array_slice($expected,(int)(floor(1/$size)*$size),$size);}elseif($kind==='empty-sort'){$get['sort_order']='';$expected_ids=array_slice(array(42,44,45,46,47),0,$size);}
   $r=cmt_controller(array(),$get);preg_match_all('/id="comment-([0-9]+)"/',$r['html'],$matches);$ids=array_map('intval',$matches[1]);nt_check($r['message']===''&&$ids===$expected_ids,'Actual XS coherent page/anchor: '.$kind);nt_check(strpos($r['html'],'sort_order=')!==false||$size>=5,'Actual pagination retains sort state');$views++;$cases++;
  }
 }}}
 foreach(array(false,true)as$reverse){cmtp_prepare();tn_sql('UPDATE fixture_ina_games SET reverse_list='.($reverse?1:0).' WHERE game_id=1');$r=cmtp_call(array('size'=>10));$rows=$r['value']['page']['rows'];$score=$reverse?'10.0000':'30.0000';$time=$reverse?'99':'8';nt_check($r['ok']&&count($rows)===5,'One comment per score history');foreach($rows as$row){if(in_array((int)$row['comment_id'],array(42,44),true)){nt_check($row['score']===$score&&$row['time_taken']===$time,'Best normal score and earliest-date duration stay paired');}elseif((int)$row['comment_id']===45){nt_check($row['score']==='25.0000'&&$row['time_taken']==='6','Other player result is independent');}else{nt_check($row['score']===null&&$row['time_taken']===null,'Former/orphan author has no unrelated score');}}$cases++;}
 cmtp_prepare();tn_sql("UPDATE fixture_users SET username='Current & name' WHERE user_id=9");tn_sql("UPDATE fixture_users SET username='Current editor' WHERE user_id=10");$r=cmtp_call(array('size'=>10));$rows=$r['value']['page']['rows'];nt_check($rows[0]['username']==='Current & name'&&$rows[1]['edit_username']==='Current editor'&&$rows[1]['comment_username']==='Old name','Current author/editor labels, historical byline retained');$cases++;
 foreach(array(array('start'=>array('nested'),'size'=>array('nested'),'sort'=>array('DESC')),array('start'=>'-1','size'=>'0','sort'=>'evil'),array('start'=>'1e9','size'=>'1e9','sort'=>''),array('start'=>'9999999999','size'=>'9999999999','sort'=>'DESC'),array('start'=>3.5,'size'=>3.5,'sort'=>null))as$options){cmtp_prepare();$r=cmtp_call($options);nt_check($r['ok']&&$r['value']['page']['size']>=1&&$r['value']['page']['size']<=1000&&$r['value']['page']['start']<=4&&count($r['value']['page']['rows'])>0&&tp_released(),'Malformed/bounded/stale options remain safe and consistent');$cases++;}
 cmtp_prepare();tn_sql("DELETE FROM fixture_ina_comment WHERE comment_game_name='synthetic-rating'");$r=cmtp_call(array('start'=>'999999','size'=>2,'sort'=>'DESC'));nt_check($r['ok']&&$r['value']['game']['comments_count']===0&&$r['value']['page']['rows']===array()&&$r['value']['page']['start']===0,'Empty game has an empty first page');$cases++;
 foreach(array('edit','delete')as$mode){cmtp_prepare();$r=cmt_controller(array(),array('game_id'=>'1','mode'=>$mode));preg_match_all('/id="comment-([0-9]+)"/',$r['html'],$matches);nt_check($r['message']===''&&array_map('intval',$matches[1])===array(42,44,45,46,47),'A missing selected ID retains ordinary listing instead of a broken edit/delete view');$cases++;$views++;}
 // A real caller transaction and old snapshot must remain untouched while
 // the independent page reader observes currently committed rows.
 cmtp_prepare();mysqli_query($db->db_connect_id,'START TRANSACTION');$r=$db->sql_query('SELECT * FROM fixture_ina_comment');$db->sql_freeresult($r);nt_check(mysqli_query($db->db_connect_id,"INSERT INTO fixture_config(config_name,config_value) VALUES('comment-page-pending','private')"),'Own pending caller work');
 try{tn_sql("UPDATE fixture_ina_comment SET comment_text='Fresh committed body' WHERE comment_id=42");tn_sql('DELETE FROM fixture_ina_comment WHERE comment_id=44');$r=cmtp_call(array('size'=>10));nt_check($r['ok']&&$r['value']['game']['comments_count']===4&&$r['value']['page']['rows'][0]['comment_text']==='Fresh committed body','Current coherent page ignores caller old snapshot');$r=$db->sql_query("SELECT config_value FROM fixture_config WHERE config_name='comment-page-pending'");$row=$db->sql_fetchrow($r);$db->sql_freeresult($r);nt_check($row['config_value']==='private'&&!tp_rows("SELECT * FROM fixture_config WHERE config_name='comment-page-pending'")&&$db->db_connect_id,'Page does not commit, rollback or close caller work');}finally{mysqli_query($db->db_connect_id,'ROLLBACK');}$cases++;
 cmtp_prepare();$fired=false;$tp_hook=function($phase,$sql)use(&$fired){if($phase==='after'&&strpos($sql,'SELECT COUNT(*) total FROM fixture_ina_comment ')===0){$GLOBALS['tp_hook']=null;tn_sql('DELETE FROM fixture_ina_comment WHERE comment_id=42');tn_sql("INSERT INTO fixture_ina_comment(comment_id,comment_game_name,comment_user_id,comment_text) VALUES(99,'synthetic-rating',9,'New peer row')");$fired=true;}};
 try{$r=cmtp_call(array('size'=>10));nt_check($r['ok']&&$fired&&$r['value']['game']['comments_count']===5&&cmtp_ids($r['value']['page'])===array(42,44,45,46,47),'Count/first/rows remain in one actual read-only snapshot across peer mutations');}finally{$tp_hook=null;}$r=cmtp_call(array('size'=>10));nt_check(cmtp_ids($r['value']['page'])===array(44,45,46,47,99),'Next read observes the peer change normally');$cases++;
 // Fail every adopted read boundary on both sides; never return partial rows.
 cmtp_prepare();$trace=array();$tp_hook=function($phase,$sql)use(&$trace){if($phase==='before'){$trace[]=$sql;}};nt_check(cmtp_call(array('sort'=>'DESC','size'=>2),42)['ok'],'Actual full selected page trace');$tp_hook=null;$owned=false;$positions=array();foreach($trace as$i=>$sql){if($sql==='SET SESSION lock_wait_timeout=3'){$owned=true;}if($owned&&$sql!=='ROLLBACK'){$positions[$i+1]=$sql;}}
 foreach($positions as$position=>$statement){foreach(array('before','after')as$phase){cmtp_prepare();$before=tp_snapshot();$seen=0;$reached=false;$tp_hook=function($event,$sql)use($position,$phase,&$seen,&$reached){if($event==='before'){$seen++;}if($event===$phase&&$seen===$position){$reached=true;return false;}};try{$r=cmtp_call(array('sort'=>'DESC','size'=>2),42);nt_check(!$r['ok']&&$reached&&tp_snapshot()===$before&&tp_released(),'Each read fault returns no partial page and changes nothing');}finally{$tp_hook=null;}$faults++;}}
 echo 'Native Arcade comment pages: '.$cases.' cases, '.$faults.' SQL faults, '.$views." actual views PASS; unique comments, paired best scores, sort-aware anchors, bounded offsets, current labels and coherent isolated snapshots.\n";
}
